const STORE='madero-chat-v2';
export function initConcierge(){
const launcher=document.createElement('button');launcher.className='chat-launcher';launcher.setAttribute('aria-controls','madero-chat');launcher.setAttribute('aria-expanded','false');launcher.innerHTML='<span class="spark" aria-hidden="true">✦</span> Ask Madero';document.body.append(launcher);
const panel=document.createElement('section');panel.id='madero-chat';panel.className='chat-panel';panel.hidden=true;panel.setAttribute('role','dialog');panel.setAttribute('aria-modal','true');panel.setAttribute('aria-labelledby','chat-title');panel.innerHTML=`<div class="chat-header"><span class="chat-avatar" aria-hidden="true">✦</span><div><strong id="chat-title">Your Madero concierge</strong><small>AI assistance · Personal care, made simple</small></div><button class="chat-close" aria-label="Close concierge">×</button></div><div class="chat-messages" role="log" aria-live="polite" aria-relevant="additions" aria-label="Conversation"></div><div class="chat-status" role="status"></div><div class="chat-shortcuts"><a href="booking.html">Book a ritual ↗</a><a href="https://wa.me/message/GV2Y37ELMB6FK1" target="_blank" rel="noopener">WhatsApp ↗</a><button class="chat-clear">New chat</button></div><form class="chat-form"><label for="chat-input">Your message</label><textarea id="chat-input" maxlength="1200" rows="1" placeholder="Ask about your next ritual…" required></textarea><button type="submit" aria-label="Send message">↑</button></form><p class="chat-disclaimer">AI can make mistakes. Confirm details with our team.<br>Messages are processed by our AI provider. <a href="privacy.html">Privacy</a></p>`;document.body.append(panel);
const messages=panel.querySelector('.chat-messages'),input=panel.querySelector('textarea'),form=panel.querySelector('form'),send=form.querySelector('button'),status=panel.querySelector('.chat-status');let history=[],busy=false,controller=null,previousFocus=null,previousOverflow='';let inerted=[];
try{const saved=JSON.parse(sessionStorage.getItem(STORE)||'[]');if(Array.isArray(saved))history=saved.filter(m=>['user','assistant'].includes(m.role)&&typeof m.content==='string').map(m=>({role:m.role,content:m.content.slice(0,4000)})).slice(-12)}catch{}
const save=()=>{try{sessionStorage.setItem(STORE,JSON.stringify(history.slice(-12)))}catch{}};
const add=(role,text,kind='')=>{const bubble=document.createElement('div');bubble.className=`chat-message ${role} ${kind}`;bubble.textContent=text;messages.append(bubble);messages.scrollTop=messages.scrollHeight;return bubble};
const greet=()=>{add('assistant','Welcome to Madero Slim. What kind of reset are you looking for? Ask me about treatments, prices, home service areas or how to book.');const suggestions=document.createElement('div');suggestions.className='chat-suggestions';for(const text of ['Help me choose','Treatments under AED 300','Do you serve my area?']){const b=document.createElement('button');b.textContent=text;b.onclick=()=>{if(!busy){input.value=text;form.requestSubmit()}};suggestions.append(b)}messages.append(suggestions)};
if(history.length)history.forEach(m=>add(m.role,m.content));else greet();
const close=()=>{panel.hidden=true;launcher.setAttribute('aria-expanded','false');for(const el of inerted)el.inert=false;inerted=[];document.body.style.overflow=previousOverflow;previousFocus?.focus()};
const open=()=>{if(!panel.hidden)return;previousFocus=document.activeElement;previousOverflow=document.body.style.overflow;panel.hidden=false;launcher.setAttribute('aria-expanded','true');document.body.style.overflow='hidden';inerted=[...document.body.children].filter(el=>el!==panel&&!el.inert&&el.tagName!=='SCRIPT');inerted.forEach(el=>el.inert=true);input.focus({preventScroll:true});messages.scrollTop=messages.scrollHeight};
launcher.onclick=open;document.querySelectorAll('.open-chat').forEach(b=>b.addEventListener('click',open));panel.querySelector('.chat-close').onclick=close;
panel.addEventListener('keydown',e=>{if(e.key==='Escape'){e.preventDefault();close()}if(e.key==='Tab'){const focusable=[...panel.querySelectorAll('a,button,textarea')].filter(e=>!e.disabled&&!e.hidden);const first=focusable[0],last=focusable.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
panel.querySelector('.chat-clear').onclick=()=>{controller?.abort();controller=null;history=[];save();messages.replaceChildren();busy=false;send.disabled=false;status.textContent='';greet();input.focus()};
input.addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.shiftKey&&!e.isComposing){e.preventDefault();form.requestSubmit()}});
form.addEventListener('submit',async e=>{e.preventDefault();const text=input.value.trim();if(!text||busy)return;busy=true;send.disabled=true;const turnController=new AbortController();controller=turnController;const timeout=setTimeout(()=>turnController.abort(),28000);add('user',text);input.value='';status.textContent='Finding the right care for you…';const conversation=[...history,{role:'user',content:text}].slice(-10);
try{const response=await fetch('/api/chat',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({messages:conversation}),signal:turnController.signal});const data=await response.json().catch(()=>({}));if(!response.ok)throw new Error(data.message||'Our AI concierge is temporarily unavailable. Please contact our team on WhatsApp.');if(typeof data.reply!=='string'||!data.reply.trim())throw new Error('The concierge could not complete this reply. Please try again.');history=[...conversation,{role:'assistant',content:data.reply}];save();add('assistant',data.reply);if(data.ai?.provider){const label=document.createElement('div');label.className='chat-ai-label';label.textContent='✦ AI-generated reply';messages.append(label)}if(Array.isArray(data.sources)&&data.sources.length){const sources=document.createElement('div');sources.className='chat-sources';for(const source of data.sources){if(!/^\/[a-z-]+\.html$/.test(source.url))continue;const a=document.createElement('a');a.textContent=source.title;a.href=source.url;sources.append(a)}messages.append(sources)}messages.scrollTop=messages.scrollHeight;
}catch(error){if(controller===turnController){const bubble=add('assistant',error.name==='AbortError'?'That took longer than expected. Please try again, or reach our team on WhatsApp.':error.message,'error');const a=document.createElement('a');a.href='https://wa.me/message/GV2Y37ELMB6FK1';a.target='_blank';a.rel='noopener';a.textContent=' Chat with our team ↗';bubble.append(a)}}finally{clearTimeout(timeout);if(controller===turnController){busy=false;send.disabled=false;status.textContent='';if(!panel.hidden)input.focus({preventScroll:true})}}});
}
